	file("/dev/tty12");
};
destination d_user {
	file("/var/log/user.log");
};
destination d_uucp {
	file("/var/log/uucp.log");
};

filter f_acpid {
	program("acpid");
};
filter f_auth {
	facility(auth);
};
filter f_authpriv {
	facility(auth, authpriv);
};
filter f_crit {
	level(crit);
};
filter f_cron {
	facility(cron);
