commands.command:
install -d -m 0755 /etc/syslog-ng/conf.d
cat > /etc/syslog-ng/conf.d/20-auth-events.conf <<'ANTRIEB_AUTH_EVENTS'
# Keep authentication and authorization facilities in a dedicated file.
destination d_auth_events {
    file("/var/log/auth-events.log"
         owner("root") group("log") perm(0640) create-dirs(no));
};
filter f_auth_events {
    facility(auth, authpriv);
};
log {
    source(s_local);
    filter(f_auth_events);
    destination(d_auth_events);
};

# Preserve conventional file-based logging for every other syslog facility.
destination d_normal_events {
    file("/var/log/messages"
         owner("root") group("log") perm(0640) create-dirs(no));
};
filter f_normal_events {
    not facility(auth, authpriv);
};
log {
    source(s_local);
    filter(f_normal_events);
    destination(d_normal_events);
};
ANTRIEB_AUTH_EVENTS
if ! grep -Fqx '@include "/etc/syslog-ng/conf.d/*.conf"' /etc/syslog-ng/syslog-ng.conf; then
    printf '\n@include "/etc/syslog-ng/conf.d/*.conf"\n' >> /etc/syslog-ng/syslog-ng.conf
fi
printf '%s\n' 'configured files:'
ls -l /etc/syslog-ng/conf.d/20-auth-events.conf /etc/syslog-ng/syslog-ng.conf

